const upsertVCSGitLabMRDetail = `-- name: UpsertVCSGitLabMRDetail :one
INSERT INTO vcs_gitlab_mr_detail (
    vcs_pull_request_id, description, merge_commit_sha, detailed_merge_status,
    target_branch, reviewers, assignees, labels, last_refreshed_at,
    last_refresh_error, conflict_sha, pipeline_sync_at, pipeline_sync_error,
    wakeup_sync_generation
)
SELECT pr.id AS vcs_pull_request_id,
       $1 AS description,
       $2 AS merge_commit_sha,
       $3 AS detailed_merge_status,
       $4 AS target_branch,
       COALESCE($5::jsonb, '[]'::jsonb) AS reviewers,
       COALESCE($6::jsonb, '[]'::jsonb) AS assignees,
       COALESCE($7::jsonb, '[]'::jsonb) AS labels,
       $8 AS last_refreshed_at,
       $9 AS last_refresh_error,
       COALESCE($10, '') AS conflict_sha,
       $11 AS pipeline_sync_at,
       $12 AS pipeline_sync_error,
       $13 AS wakeup_sync_generation
FROM vcs_pull_request pr
WHERE pr.id = $14
  AND pr.workspace_id = $15
  AND pr.provider = 'gitlab'
  AND pr.wakeup_sync_generation = $13
ON CONFLICT (vcs_pull_request_id) DO UPDATE SET
    description = EXCLUDED.description,
    merge_commit_sha = EXCLUDED.merge_commit_sha,
    detailed_merge_status = EXCLUDED.detailed_merge_status,
    target_branch = EXCLUDED.target_branch,
    reviewers = EXCLUDED.reviewers,
    assignees = EXCLUDED.assignees,
    labels = EXCLUDED.labels,
    last_refreshed_at = EXCLUDED.last_refreshed_at,
    last_refresh_error = EXCLUDED.last_refresh_error,
    conflict_sha = EXCLUDED.conflict_sha,
    pipeline_sync_at = EXCLUDED.pipeline_sync_at,
    pipeline_sync_error = EXCLUDED.pipeline_sync_error,
    wakeup_sync_generation = EXCLUDED.wakeup_sync_generation,
    updated_at = now()
WHERE EXCLUDED.wakeup_sync_generation >= vcs_gitlab_mr_detail.wakeup_sync_generation
  AND EXISTS (
      SELECT 1 FROM vcs_pull_request current_pr
      WHERE current_pr.id = EXCLUDED.vcs_pull_request_id
        AND current_pr.workspace_id = $15
        AND current_pr.wakeup_sync_generation = $13
  )
RETURNING vcs_pull_request_id, description, merge_commit_sha, detailed_merge_status, target_branch, reviewers, assignees, labels, last_refreshed_at, last_refresh_error, conflict_sha, pipeline_sync_at, pipeline_sync_error, wakeup_sync_generation, created_at, updated_at
`

